def minimum_ship_capacity(weights, days):
 def needed(capacity):
  used=1;load=0
  for weight in weights:
   if load+weight>capacity:used+=1;load=0
   load+=weight
  return used
 low,high=max(weights),sum(weights)
 while low<high:
  middle=(low+high)//2
  if needed(middle)<=days:high=middle
  else:low=middle+1
 return low

